import{_ as l,a0 as r,w as p,s as d,ao as o,I as n,x as s,a1 as i,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何知道你是否使用了代理服务器？ | LCTT x X-CMD","titleTemplate":false,"description":"如何知道你是否使用了代理服务器？ | LCTT (202303) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何知道你是否使用了代理服务器？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何知道你是否使用了代理服务器？ | LCTT (202303) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202303/20230315.1 ⭐️ How to know if You are Behind a Proxy Server","title":"如何知道你是否使用了代理服务器？","tag":"202303","desc":""},"relativePath":"202303/20230315.1 ⭐️ How to know if You are Behind a Proxy Server.md","filePath":"[post].md"}'),h={name:"202303/20230315.1 ⭐️ How to know if You are Behind a Proxy Server.md"};function g(u,t,c,k,b,m){const e=r("Link");return p(),d("div",null,[t[18]||(t[18]=o('<h1 id="如何知道你是否使用了代理服务器" tabindex="-1">如何知道你是否使用了代理服务器？ <a class="header-anchor" href="#如何知道你是否使用了代理服务器" aria-label="Permalink to “如何知道你是否使用了代理服务器？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202303/24/174021wkdzn81kvtnngzaw.jpg" alt=""></p><p>什么是代理？</p><p>代理是充当客户端和另一台服务器之间的中介的服务器或软件应用。它充当客户端和互联网之间的网关，允许用户访问在线资源，同时隐藏他们的身份、位置和其他个人信息。</p><p>代理通常用于增强安全性和隐私，并为你的网络添加过滤器/防火墙。</p><p>有几种类型的代理，如 HTTP 代理、SOCKS 代理、透明代理等。</p><p>除非你在透明代理后面，否则检查起来毫不费力。在这里，我将讨论检测透明代理和常用代理的方法。</p><h3 id="如何检查你是否在透明代理后面" tabindex="-1">如何检查你是否在透明代理后面 <a class="header-anchor" href="#如何检查你是否在透明代理后面" aria-label="Permalink to “如何检查你是否在透明代理后面”">​</a></h3><p>虽然每种类型的代理都有其特性和功能，但如果它是透明代理，你将无法在客户端的 PC 上检测到它。这是因为透明代理在后台静默运行，拦截所有流量而不修改它。</p><p>有时，可能是你的互联网服务提供商和内容交付网络使用它们来缓存资源的副本以节省带宽或只是为了监视/过滤网络。</p><p>有几种方法可以检查你是否在透明代理后面：</p><ul><li><strong>通过某些在线 IP 检测/检查网站获得的 IP 地址可能与你的计算机或设备的 IP 地址不匹配</strong>。因为代理服务器正在拦截你的流量并将其与 IP 地址一起发送出去。</li><li><strong>检查你的网络设置以查看是否配置了代理服务器。</strong></li><li><strong>借助一些在线代理检测工具。</strong></li><li><strong>连接到你知道不存在的服务器。</strong> 如果网页上显示的错误看起来与平时不同，你可能使用了代理。</li></ul>',12)),n("p",null,[t[1]||(t[1]=s("无论你喜欢与否，你始终可以使用 ",-1)),i(e,{href:"https://itsfoss.com/best-vpn-linux/"},{default:a(()=>[...t[0]||(t[0]=[s("VPN 服务",-1)])]),_:1}),t[2]||(t[2]=s(" 绕过透明代理。",-1))]),t[19]||(t[19]=o('<h3 id="如何检查你是否在-ubuntu-上使用代理" tabindex="-1">如何检查你是否在 Ubuntu 上使用代理 <a class="header-anchor" href="#如何检查你是否在-ubuntu-上使用代理" aria-label="Permalink to “如何检查你是否在 Ubuntu 上使用代理”">​</a></h3><p>Ubuntu 或任何其他 Linux 发行版提供了多种检查方法。此处使用运行 GNOME 的 Ubuntu 22.10。</p><h4 id="使用-gnome-设置" tabindex="-1">使用 GNOME 设置 <a class="header-anchor" href="#使用-gnome-设置" aria-label="Permalink to “使用 GNOME 设置”">​</a></h4><p>这是直接的 GUI 方式。打开 GNOME <ruby>设置<rt>Settings</rt></ruby> 并转到 “<ruby>网络<rt>Networks</rt></ruby>” 选项卡，然后按旁边的齿轮图标。</p><p><img src="https://itsfoss.com/content/images/2023/02/select-the-gear-icon-adjacent-to-proxy.png" alt="Select the gear icon adjacent to the Network proxy section"></p><p>它应该默认 <ruby>禁用<rt>Disabled</rt></ruby>。</p><p>如果你在代理后面，你可以在这里看到不同的状态。在代理设置中，你可以看到，我在这里使用了代理（手动配置）。</p><p><img src="https://itsfoss.com/content/images/2023/02/Proxy-in-GNOME-settings.png" alt="Proxy details in GNOME Settings"></p><p>可以使用 GNOME 桌面中的 <code>gsettings</code> 命令更改相同的代理状态。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gsettings set org.gnome.system.proxy mode &#39;none&#39;</span></span></code></pre></div><p>你可以将 <code>none</code> 替换为 <code>auto</code> 或 <code>manual</code>。请记住，此设置是临时的，仅适用于当前用户。</p><h4 id="使用命令行" tabindex="-1">使用命令行 <a class="header-anchor" href="#使用命令行" aria-label="Permalink to “使用命令行”">​</a></h4><p>你可以通过命令行以多种方式获取代理的状态。</p><h5 id="通过列出关联的环境变量获取代理的状态" tabindex="-1">通过列出关联的环境变量获取代理的状态 <a class="header-anchor" href="#通过列出关联的环境变量获取代理的状态" aria-label="Permalink to “通过列出关联的环境变量获取代理的状态”">​</a></h5><p>打开终端并运行以下任一命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>env | grep -i proxy</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat /etc/environment | grep -i proxy</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>set | grep -i proxy</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/02/set_grep_proxy.png" alt="Using set command to check Proxy variables"></p><p>空输出意味着没有配置代理。否则，它将打印相关的环境变量。</p><blockquote><p>🚧 请注意，如果你将代理设置为环境变量，这将起作用。</p></blockquote><p>或者，你可以回显每个代理变量以检查是否设置了特定的代理变量。</p><p>以下是你可以在终端中输入的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $http_proxy</span></span></code></pre></div><h5 id="使用-nmcli-命令检查" tabindex="-1">使用 nmcli 命令检查 <a class="header-anchor" href="#使用-nmcli-命令检查" aria-label="Permalink to “使用 nmcli 命令检查”">​</a></h5><p>打开终端并输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nmcli connection show</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/02/nmcli-connection-show.png" alt="List all the connections using nmcli command"></p><p>这将列出你的连接和关联的 UUID 编号。记下要检查的连接的 UUID 编号。然后使用命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nmcli connection show &lt;UUID or name&gt; | grep -i &quot;proxy&quot;</span></span></code></pre></div><p>这将列出变量，你可以在其中记下代理服务器和端口。</p><p><img src="https://itsfoss.com/content/images/2023/02/proxy-using-nmcli.png" alt="Proxy details using nmcli command"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>我希望本指南可以帮助你了解你是否在使用代理。</p><p>我必须提一下，<strong>并非所有代理配置都是恶意的。</strong></p><p>但是，了解你的系统是否配置了代理很重要。</p><hr>',37)),n("p",null,[t[4]||(t[4]=s("via: ",-1)),i(e,{href:"https://itsfoss.com/check-proxy-server/"},{default:a(()=>[...t[3]||(t[3]=[s("https://itsfoss.com/check-proxy-server/",-1)])]),_:1})]),n("p",null,[t[9]||(t[9]=s("作者：",-1)),i(e,{href:"https://itsfoss.com/author/sreenath/"},{default:a(()=>[...t[5]||(t[5]=[s("Sreenath",-1)])]),_:1}),t[10]||(t[10]=s(" 选题：",-1)),i(e,{href:"https://github.com/lkxed/"},{default:a(()=>[...t[6]||(t[6]=[s("lkxed",-1)])]),_:1}),t[11]||(t[11]=s(" 译者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:a(()=>[...t[7]||(t[7]=[s("geekpi",-1)])]),_:1}),t[12]||(t[12]=s(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[8]||(t[8]=[s("wxy",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=s("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[13]||(t[13]=[s("LCTT",-1)])]),_:1}),t[16]||(t[16]=s(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:a(()=>[...t[14]||(t[14]=[s("Linux中国",-1)])]),_:1}),t[17]||(t[17]=s(" 荣誉推出",-1))])])}const C=l(h,[["render",g]]);export{y as __pageData,C as default};
